    "dep_name": "المنطقة الشرقية",
    "x": 410.6,
    "y": 338.1,
    "fakt": "الأَحْسَاءُ أَكْبَرُ وَاحَةٍ فِي العَالَم: مِلْيُونَا نَخْلَةٍ وَعُيُونٌ حَارَّةٌ وَسُوقُ القَيْصَرِيَّة.",
    "fakt_de": "Al-Ahsa ist die größte Oase der Welt: zwei Millionen Palmen, heiße Quellen und der Qaisariya-Markt.",
