    "fakt": "القَطِيفُ مَدِينَةُ الصَّيَّادِين. مِنْ هُنَا كَانَتْ تَخْرُجُ سُفُنُ اللُّؤْلُؤِ قَبْلَ النَّفْط.",
    "fakt_de": "Qatif ist die Stadt der Fischer. Von hier fuhren vor dem Öl die Perlenboote aus.",
