    "fakt": "رِجَالُ أَلْمَعَ قَرْيَةٌ مِنْ بُيُوتٍ حَجَرِيَّةٍ عَالِيَة. النِّسَاءُ يَرْسُمْنَ جُدْرَانَهَا مِنَ الدَّاخِلِ بِأَلْوَانٍ زَاهِيَة: القَطّ العَسِيرِيّ.",
    "fakt_de": "Rijal Almaa ist ein Dorf aus hohen Steinhäusern. Die Frauen bemalen die Wände innen in leuchtenden Farben, al-Qatt al-Asiri.",
